-- Generated by matugen from .config/matugen/templates/nvim-colors.lua, do not edit by hand
-- Neovim colorscheme. Load it with: :colorscheme matugen
-- Neutral colors follow the wallpaper, hues are fixed (custom_colors in config.toml).
-- Normal has no background on purpose, so kitty transparency stays (like in yazi).

vim.o.background = 'dark'
vim.cmd('highlight clear')
vim.g.colors_name = 'matugen'

local c = {
  fg        = '{{colors.on_surface.default.hex}}',
  muted     = '{{colors.on_surface_variant.default.hex}}',
  dim       = '{{colors.outline_variant.default.hex}}',
  surface   = '{{colors.surface.default.hex}}',
  raised    = '{{colors.surface_container_high.default.hex}}',
  accent    = '{{colors.primary.default.hex}}',
  on_accent = '{{colors.on_primary.default.hex}}',
  selected  = '{{colors.primary_container.default.hex}}',
  red       = '{{colors.red_source.default.hex}}',
  yellow    = '{{colors.yellow_source.default.hex}}',
  green     = '{{colors.green_source.default.hex}}',
  blue      = '{{colors.blue_source.default.hex}}',
  purple    = '{{colors.purple_source.default.hex}}',
  cyan      = '{{colors.cyan_source.default.hex}}',
}

local groups = {
  -- Editor UI
  Normal       = { fg = c.fg },
  NormalFloat  = { fg = c.fg, bg = c.raised },
  FloatBorder  = { fg = c.dim, bg = c.raised },
  FloatTitle   = { fg = c.accent, bg = c.raised, bold = true },
  CursorLine   = { bg = c.raised },
  CursorLineNr = { fg = c.accent, bold = true },
  LineNr       = { fg = c.dim },
  EndOfBuffer  = { fg = c.dim },
  NonText      = { fg = c.dim },
  Whitespace   = { fg = c.dim },
  SpecialKey   = { fg = c.dim },
  WinSeparator = { fg = c.dim },
  ColorColumn  = { bg = c.raised },
  Conceal      = { fg = c.dim },
  Visual       = { bg = c.selected },
  Search       = { fg = c.surface, bg = c.yellow },
  CurSearch    = { fg = c.surface, bg = c.accent },
  IncSearch    = { fg = c.surface, bg = c.accent },
  MatchParen   = { fg = c.yellow, bold = true, underline = true },
  Folded       = { fg = c.muted, bg = c.raised },
  FoldColumn   = { fg = c.dim },
  -- No bg: the statusline stays transparent (lualine sections inherit this)
  StatusLine   = { fg = c.fg },
  StatusLineNC = { fg = c.muted },
  TabLine      = { fg = c.muted, bg = c.raised },
  TabLineSel   = { fg = c.on_accent, bg = c.accent, bold = true },
  TabLineFill  = { bg = c.raised },
  Pmenu        = { fg = c.fg, bg = c.raised },
  PmenuSel     = { fg = c.on_accent, bg = c.accent },
  PmenuSbar    = { bg = c.raised },
  PmenuThumb   = { bg = c.dim },
  Directory    = { fg = c.blue },
  Title        = { fg = c.accent, bold = true },
  Question     = { fg = c.green },
  ErrorMsg     = { fg = c.red },
  WarningMsg   = { fg = c.yellow },
  ModeMsg      = { fg = c.fg, bold = true },
  MoreMsg      = { fg = c.green },

  -- Syntax (treesitter @captures link to these standard groups by default)
  Comment    = { fg = c.muted, italic = true },
  Constant   = { fg = c.purple },
  String     = { fg = c.green },
  Character  = { fg = c.green },
  Number     = { fg = c.purple },
  Boolean    = { fg = c.purple },
  Float      = { fg = c.purple },
  Identifier = { fg = c.fg },
  Function   = { fg = c.blue },
  Statement  = { fg = c.purple },
  Operator   = { fg = c.cyan },
  PreProc    = { fg = c.cyan },
  Type       = { fg = c.yellow },
  Special    = { fg = c.cyan },
  Delimiter  = { fg = c.muted },
  Underlined = { fg = c.blue, underline = true },
  Error      = { fg = c.red },
  Todo       = { fg = c.surface, bg = c.yellow, bold = true },
  Added      = { fg = c.green },
  Changed    = { fg = c.yellow },
  Removed    = { fg = c.red },

  -- Diff
  DiffAdd    = { fg = c.green, bg = c.raised },
  DiffChange = { fg = c.yellow, bg = c.raised },
  DiffDelete = { fg = c.red },
  DiffText   = { fg = c.on_accent, bg = c.accent },

  -- Diagnostics
  DiagnosticError          = { fg = c.red },
  DiagnosticWarn           = { fg = c.yellow },
  DiagnosticInfo           = { fg = c.blue },
  DiagnosticHint           = { fg = c.cyan },
  DiagnosticOk             = { fg = c.green },
  DiagnosticUnderlineError = { undercurl = true, sp = c.red },
  DiagnosticUnderlineWarn  = { undercurl = true, sp = c.yellow },
  DiagnosticUnderlineInfo  = { undercurl = true, sp = c.blue },
  DiagnosticUnderlineHint  = { undercurl = true, sp = c.cyan },
  DiagnosticUnderlineOk    = { undercurl = true, sp = c.green },
  SpellBad                 = { undercurl = true, sp = c.red },
}

for name, spec in pairs(groups) do
  vim.api.nvim_set_hl(0, name, spec)
end
